"use client";

import { useState, useEffect } from "react";
import {
  Box,
  Button,
  Chip,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  LinearProgress,
  Divider,
} from "@mui/material";
import {
  BarChart,
  Download,
  TrendingDown,
  TrendingUp,
  TrendingFlat,
} from "@mui/icons-material";
import { exportToPDF } from "@/lib/report-pdf";
import { getMonthlyReportAction } from "@/features/report/actions";
import { getIncomeListAction } from "@/features/income/actions";
import { getOutcomeListAction } from "@/features/outcome/actions";
import { getEnumsAction } from "@/features/enum/actions";
import type { MonthlyEntry, CategoryEntry } from "@/types/report.type";

// ─── Helpers ─────────────────────────────────────────────────────────────────
const formatIDR = (n: number) =>
  new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(n);

const cellSx = {
  borderColor: "rgba(255,255,255,0.05)",
  color: "#cbd5e1",
  fontSize: "0.8125rem",
  py: 1.75,
};

const headCellSx = {
  borderColor: "rgba(255,255,255,0.05)",
  backgroundColor: "#0b1829",
  color: "#64748b",
  fontSize: "0.6875rem",
  fontWeight: 700,
  letterSpacing: "0.06em",
  textTransform: "uppercase" as const,
  py: 1.5,
};

// ─── Component ────────────────────────────────────────────────────────────────
export default function MonthlyReportPage() {
  const [selectedYear, setSelectedYear] = useState("2026");
  const [years, setYears] = useState<string[]>(["2026", "2025"]);
  const [allData, setAllData] = useState<MonthlyEntry[]>([]);
  const [categories, setCategories] = useState<CategoryEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      setLoading(true);
      try {
        const [monthlyRes, incomesRes, outcomesRes, typeRes, srcRes, catRes, subRes] = await Promise.all([
          getMonthlyReportAction(),
          getIncomeListAction({ page: 1, pageSize: 1000 }),
          getOutcomeListAction({ page: 1, pageSize: 1000 }),
          getEnumsAction('income_type'),
          getEnumsAction('income_source'),
          getEnumsAction('outcome_category'),
          getEnumsAction('outcome_subcategory'),
        ]);

        // 1. Process Monthly Data
        const monthlyList: MonthlyEntry[] = Array.isArray(monthlyRes) ? monthlyRes : [];
        setAllData(monthlyList);

        // Extract unique years
        const uniqueYears = Array.from(
          new Set([
            ...monthlyList.map((item) => item.bulan.split("-")[0]),
            new Date().getFullYear().toString(),
          ])
        ).sort((a, b) => b.localeCompare(a));
        setYears(uniqueYears);
        if (uniqueYears.length > 0 && !uniqueYears.includes(selectedYear)) {
          setSelectedYear(uniqueYears[0]);
        }

        // Enums mapping
        const typeMap = Object.fromEntries((typeRes?.success ? typeRes.data : []).map((t: any) => [t.id, t.value]));
        const srcMap = Object.fromEntries((srcRes?.success ? srcRes.data : []).map((s: any) => [s.id, s.value]));
        const catMap = Object.fromEntries((catRes?.success ? catRes.data : []).map((c: any) => [c.id, c.value]));
        const subMap = Object.fromEntries((subRes?.success ? subRes.data : []).map((s: any) => [s.id, s.value]));

        const rawIncomes = incomesRes?.success ? (incomesRes.data?.items || incomesRes.data || []) : [];
        const rawOutcomes = outcomesRes?.success ? (outcomesRes.data?.items || outcomesRes.data || []) : [];

        // Calculate Category Breakdown dynamically for current selectedYear
        const incMap = new Map<string, number>();
        let yearIncTotal = 0;
        rawIncomes.forEach((i: any) => {
          const year = new Date(i.date).getFullYear().toString();
          if (year === selectedYear) {
            const label = srcMap[i.sourceId] || typeMap[i.typeId] || "Lainnya";
            const amt = Number(i.amount || 0);
            incMap.set(label, (incMap.get(label) || 0) + amt);
            yearIncTotal += amt;
          }
        });

        const outMap = new Map<string, number>();
        let yearOutTotal = 0;
        rawOutcomes.forEach((o: any) => {
          const year = new Date(o.date).getFullYear().toString();
          if (year === selectedYear) {
            const label = subMap[o.subcategoryId] || catMap[o.categoryId] || "Lainnya";
            const amt = Number(o.amount || 0);
            outMap.set(label, (outMap.get(label) || 0) + amt);
            yearOutTotal += amt;
          }
        });

        const cats: CategoryEntry[] = [];
        incMap.forEach((nominal, label) => {
          cats.push({
            kategori: label,
            tipe: "Pemasukan",
            nominal,
            persen: yearIncTotal > 0 ? parseFloat(((nominal / yearIncTotal) * 100).toFixed(1)) : 0,
          });
        });

        outMap.forEach((nominal, label) => {
          cats.push({
            kategori: label,
            tipe: "Pengeluaran",
            nominal,
            persen: yearOutTotal > 0 ? parseFloat(((nominal / yearOutTotal) * 100).toFixed(1)) : 0,
          });
        });

        setCategories(cats);
      } catch (err) {
        console.error("Error fetching report data:", err);
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, [selectedYear]);

  // Filter monthly data by selected year
  const data = allData.filter((row) => row.bulan.startsWith(selectedYear));

  const totalPemasukan = data.reduce((s, r) => s + r.pemasukan, 0);
  const totalPengeluaran = data.reduce((s, r) => s + r.pengeluaran, 0);
  const totalNet = totalPemasukan - totalPengeluaran;
  const tabunganRate = totalPemasukan > 0 ? ((totalPemasukan - totalPengeluaran) / totalPemasukan) * 100 : 0;

  const incomeCategories = categories.filter((c) => c.tipe === "Pemasukan").sort((a, b) => b.nominal - a.nominal);
  const expenseCategories = categories.filter((c) => c.tipe === "Pengeluaran").sort((a, b) => b.nominal - a.nominal);

  const categoryColors: Record<string, string> = {
    "Gaji Bulanan": "#6366f1",
    Freelance: "#22c55e",
    "Sewa Properti": "#f59e0b",
    "Dividen & Bunga": "#06b6d4",
    "Kebutuhan Pokok": "#f59e0b",
    Transportasi: "#3b82f6",
    Utilitas: "#8b5cf6",
    Investasi: "#22c55e",
    Kesehatan: "#10b981",
    "Hiburan & Pendidikan": "#ec4899",
    Lainnya: "#64748b",
  };

  const handleExportPDF = () => {
    const headers = ["Bulan", "Pemasukan", "Pengeluaran", "Net", "Saving Rate"];
    const rows = data.map((row) => {
      const net = row.pemasukan - row.pengeluaran;
      const savRate = row.pemasukan > 0 ? `${((net / row.pemasukan) * 100).toFixed(1)}%` : "0%";
      return [
        row.bulanLabel,
        formatIDR(row.pemasukan),
        formatIDR(row.pengeluaran),
        `${net >= 0 ? "+" : ""}${formatIDR(net)}`,
        savRate
      ];
    });

    const meta = [
      { label: "Total Pemasukan", value: formatIDR(totalPemasukan) },
      { label: "Total Pengeluaran", value: formatIDR(totalPengeluaran) },
      { label: "Net Kumulatif", value: formatIDR(totalNet) },
      { label: "Saving Rate", value: `${tabunganRate.toFixed(1)}%` }
    ];

    exportToPDF(
      `Monthly Financial Report — Tahun ${selectedYear}`,
      headers,
      rows,
      `Monthly_Report_${selectedYear}.pdf`,
      meta
    );
  };

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      {/* ── Header ─────────────────────────────────────────────────────── */}
      <Box sx={{ mb: 4, display: "flex", alignItems: "flex-start", justifyContent: "space-between", flexWrap: "wrap", gap: 2 }}>
        <Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 1.5, mb: 0.5 }}>
            <Box
              sx={{
                width: 36,
                height: 36,
                borderRadius: "10px",
                backgroundColor: "rgba(99,102,241,0.15)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <BarChart sx={{ fontSize: 18, color: "#818cf8" }} />
            </Box>
            <Typography variant="h5" sx={{ fontWeight: 700, color: "#f1f5f9", fontSize: "1.25rem" }}>
              Monthly Report
            </Typography>
          </Box>
          <Typography variant="body2" sx={{ color: "#64748b", ml: "52px" }}>
            Rekapitulasi keuangan per bulan dalam satu tahun
          </Typography>
        </Box>

        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <InputLabel sx={{ color: "#64748b", fontSize: "0.8125rem", "&.Mui-focused": { color: "#818cf8" } }}>
              Tahun
            </InputLabel>
            <Select
              value={selectedYear}
              label="Tahun"
              onChange={(e) => setSelectedYear(e.target.value)}
              sx={{
                color: "#cbd5e1",
                fontSize: "0.8125rem",
                backgroundColor: "#0f1e38",
                borderRadius: "10px",
                "& fieldset": { borderColor: "rgba(255,255,255,0.08)" },
                "&:hover fieldset": { borderColor: "rgba(99,102,241,0.4)" },
                "&.Mui-focused fieldset": { borderColor: "#6366f1" },
                "& .MuiSvgIcon-root": { color: "#64748b" },
              }}
            >
              {years.map((y) => (
                <MenuItem key={y} value={y} sx={{ fontSize: "0.8125rem" }}>
                  {y}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <Button
            size="small"
            variant="outlined"
            onClick={handleExportPDF}
            startIcon={<Download sx={{ fontSize: 16 }} />}
            sx={{
              borderColor: "rgba(255,255,255,0.1)",
              color: "#94a3b8",
              borderRadius: "10px",
              textTransform: "none",
              fontSize: "0.8125rem",
              px: 2,
              "&:hover": { borderColor: "#6366f1", color: "#c7d2fe", backgroundColor: "rgba(99,102,241,0.08)" },
            }}
          >
            Export
          </Button>
        </Box>
      </Box>

      {/* ── KPI Summary ─────────────────────────────────────────────────── */}
      <Box sx={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 2, mb: 3 }}>
        {[
          {
            label: "Total Pemasukan",
            value: formatIDR(totalPemasukan),
            sub: `${data.length} bulan`,
            color: "#22c55e",
          },
          {
            label: "Total Pengeluaran",
            value: formatIDR(totalPengeluaran),
            sub: `${data.length} bulan`,
            color: "#ef4444",
          },
          {
            label: "Net Income",
            value: formatIDR(totalNet),
            sub: "Surplus kumulatif",
            color: totalNet >= 0 ? "#818cf8" : "#f87171",
          },
          {
            label: "Saving Rate",
            value: `${tabunganRate.toFixed(1)}%`,
            sub: "Dari total pemasukan",
            color: "#f59e0b",
          },
        ].map((c) => (
          <Paper
            key={c.label}
            elevation={0}
            sx={{
              p: 2.5,
              borderRadius: "14px",
              backgroundColor: "#0f1e38",
              border: "1px solid rgba(255,255,255,0.05)",
            }}
          >
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em", mb: 1 }}>
              {c.label}
            </Typography>
            <Typography sx={{ fontSize: "1.25rem", fontWeight: 700, color: c.color, lineHeight: 1.2 }}>
              {c.value}
            </Typography>
            <Typography sx={{ fontSize: "0.75rem", color: "#475569", mt: 0.5 }}>
              {c.sub}
            </Typography>
          </Paper>
        ))}
      </Box>

      {/* ── Monthly Breakdown Table ──────────────────────────────────────── */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: "16px",
          backgroundColor: "#0f1e38",
          border: "1px solid rgba(255,255,255,0.05)",
          overflow: "hidden",
          mb: 3,
        }}
      >
        <Box sx={{ px: 3, py: 2, borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <Typography sx={{ fontWeight: 600, color: "#e2e8f0", fontSize: "0.9375rem" }}>
            Rekap Bulanan — {selectedYear}
          </Typography>
          <Chip
            label={`${data.length} bulan`}
            size="small"
            sx={{ fontSize: "0.6875rem", backgroundColor: "rgba(99,102,241,0.15)", color: "#818cf8", fontWeight: 600, height: 22, borderRadius: "6px" }}
          />
        </Box>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell sx={headCellSx}>Bulan</TableCell>
                <TableCell sx={{ ...headCellSx, textAlign: "right" }}>Pemasukan</TableCell>
                <TableCell sx={{ ...headCellSx, textAlign: "right" }}>Pengeluaran</TableCell>
                <TableCell sx={{ ...headCellSx, textAlign: "right" }}>Net</TableCell>
                <TableCell sx={{ ...headCellSx, textAlign: "right" }}>Saving Rate</TableCell>
                <TableCell sx={headCellSx}>Tren</TableCell>
                <TableCell sx={{ ...headCellSx, textAlign: "center" }}>Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={7} sx={{ ...cellSx, textAlign: "center", py: 4 }}>
                    Loading data...
                  </TableCell>
                </TableRow>
              ) : data.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} sx={{ ...cellSx, textAlign: "center", py: 4 }}>
                    Tidak ada transaksi di tahun {selectedYear}.
                  </TableCell>
                </TableRow>
              ) : (
                data.map((row, i) => {
                  const net = row.pemasukan - row.pengeluaran;
                  const savRate = row.pemasukan > 0 ? ((net / row.pemasukan) * 100).toFixed(1) : "0.0";
                  const prevNet = i > 0 ? data[i - 1].pemasukan - data[i - 1].pengeluaran : null;
                  const tren = prevNet === null ? null : net > prevNet ? "up" : net < prevNet ? "down" : "flat";

                  return (
                    <TableRow
                      key={row.bulan}
                      sx={{
                        backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.015)",
                        "&:hover": { backgroundColor: "rgba(99,102,241,0.06)" },
                        transition: "background-color 0.15s",
                      }}
                    >
                      <TableCell sx={{ ...cellSx, color: "#e2e8f0", fontWeight: 600 }}>
                        {row.bulanLabel}
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right", color: "#22c55e", fontWeight: 600 }}>
                        {formatIDR(row.pemasukan)}
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right", color: "#ef4444", fontWeight: 600 }}>
                        {formatIDR(row.pengeluaran)}
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right", fontWeight: 700, color: net >= 0 ? "#818cf8" : "#f87171" }}>
                        {net >= 0 ? "+" : ""}{formatIDR(net)}
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right" }}>
                        <Box sx={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 1 }}>
                          <Typography sx={{ fontSize: "0.8125rem", color: parseFloat(savRate) >= 30 ? "#22c55e" : "#f59e0b", fontWeight: 700 }}>
                            {savRate}%
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell sx={cellSx}>
                        {tren === null ? (
                          <Typography sx={{ fontSize: "0.75rem", color: "#475569" }}>—</Typography>
                        ) : tren === "up" ? (
                          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                            <TrendingUp sx={{ fontSize: 14, color: "#22c55e" }} />
                            <Typography sx={{ fontSize: "0.75rem", color: "#22c55e", fontWeight: 600 }}>Naik</Typography>
                          </Box>
                        ) : tren === "down" ? (
                          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                            <TrendingDown sx={{ fontSize: 14, color: "#ef4444" }} />
                            <Typography sx={{ fontSize: "0.75rem", color: "#ef4444", fontWeight: 600 }}>Turun</Typography>
                          </Box>
                        ) : (
                          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                            <TrendingFlat sx={{ fontSize: 14, color: "#64748b" }} />
                            <Typography sx={{ fontSize: "0.75rem", color: "#64748b", fontWeight: 600 }}>Stabil</Typography>
                          </Box>
                        )}
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "center" }}>
                        <Chip
                          label={net >= 0 ? "Surplus" : "Defisit"}
                          size="small"
                          sx={{
                            fontSize: "0.6875rem",
                            height: 22,
                            fontWeight: 700,
                            borderRadius: "6px",
                            backgroundColor: net >= 0 ? "rgba(34,197,94,0.12)" : "rgba(239,68,68,0.12)",
                            color: net >= 0 ? "#22c55e" : "#ef4444",
                            border: `1px solid ${net >= 0 ? "rgba(34,197,94,0.25)" : "rgba(239,68,68,0.25)"}`,
                          }}
                        />
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Footer */}
        <Divider sx={{ borderColor: "rgba(255,255,255,0.05)" }} />
        <Box sx={{ px: 3, py: 2.5, display: "flex", justifyContent: "flex-end", gap: 4 }}>
          <Box sx={{ textAlign: "right" }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Total Pemasukan
            </Typography>
            <Typography sx={{ fontSize: "1rem", fontWeight: 700, color: "#22c55e" }}>
              {formatIDR(totalPemasukan)}
            </Typography>
          </Box>
          <Box sx={{ textAlign: "right" }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Total Pengeluaran
            </Typography>
            <Typography sx={{ fontSize: "1rem", fontWeight: 700, color: "#ef4444" }}>
              {formatIDR(totalPengeluaran)}
            </Typography>
          </Box>
          <Box sx={{ textAlign: "right", pl: 3, borderLeft: "1px solid rgba(255,255,255,0.08)" }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Net Kumulatif
            </Typography>
            <Typography sx={{ fontSize: "1.125rem", fontWeight: 800, color: "#818cf8" }}>
              {formatIDR(totalNet)}
            </Typography>
          </Box>
        </Box>
      </Paper>

      {/* ── Category Breakdown ───────────────────────────────────────────── */}
      <Box sx={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 3 }}>
        {[
          { title: "Breakdown Pemasukan", categories: incomeCategories, color: "#22c55e" },
          { title: "Breakdown Pengeluaran", categories: expenseCategories, color: "#ef4444" },
        ].map((section) => (
          <Paper
            key={section.title}
            elevation={0}
            sx={{
              borderRadius: "16px",
              backgroundColor: "#0f1e38",
              border: "1px solid rgba(255,255,255,0.05)",
              overflow: "hidden",
            }}
          >
            <Box sx={{ px: 3, py: 2, borderBottom: "1px solid rgba(255,255,255,0.05)" }}>
              <Typography sx={{ fontWeight: 600, color: "#e2e8f0", fontSize: "0.9375rem" }}>
                {section.title}
              </Typography>
            </Box>
            <Box sx={{ p: 2.5 }}>
              {loading ? (
                <Typography sx={{ color: "#64748b", fontSize: "0.8125rem", textAlign: "center" }}>
                  Loading breakdown...
                </Typography>
              ) : section.categories.length === 0 ? (
                <Typography sx={{ color: "#64748b", fontSize: "0.8125rem", textAlign: "center", py: 2 }}>
                  Tidak ada data kategori.
                </Typography>
              ) : (
                section.categories.map((cat) => (
                  <Box key={cat.kategori} sx={{ mb: 2.5 }}>
                    <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 0.75 }}>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Box
                          sx={{
                            width: 8,
                            height: 8,
                            borderRadius: "50%",
                            backgroundColor: categoryColors[cat.kategori] ?? "#64748b",
                            flexShrink: 0,
                          }}
                        />
                        <Typography sx={{ fontSize: "0.8125rem", color: "#94a3b8" }}>
                          {cat.kategori}
                        </Typography>
                      </Box>
                      <Box sx={{ textAlign: "right" }}>
                        <Typography sx={{ fontSize: "0.8125rem", fontWeight: 700, color: "#e2e8f0" }}>
                          {formatIDR(cat.nominal)}
                        </Typography>
                      </Box>
                    </Box>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                      <Box sx={{ flex: 1 }}>
                        <LinearProgress
                          variant="determinate"
                          value={cat.persen}
                          sx={{
                            height: 5,
                            borderRadius: "3px",
                            backgroundColor: "rgba(255,255,255,0.06)",
                            "& .MuiLinearProgress-bar": {
                              backgroundColor: categoryColors[cat.kategori] ?? "#64748b",
                              borderRadius: "3px",
                            },
                          }}
                        />
                      </Box>
                      <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 600, minWidth: 36, textAlign: "right" }}>
                        {cat.persen}%
                      </Typography>
                    </Box>
                  </Box>
                ))
              )}
            </Box>
          </Paper>
        ))}
      </Box>
    </Box>
  );
}
